--
-- Table structure for table `product_reviews`
--

DROP TABLE IF EXISTS `product_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_reviews` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint(20) unsigned NOT NULL COMMENT 'ID sản phẩm được đánh giá',
  `user_id` bigint(20) unsigned NOT NULL COMMENT 'ID khách hàng đánh giá',
  `order_id` bigint(20) unsigned DEFAULT NULL COMMENT 'ID đơn hàng đã mua (nếu có)',
  `rating` tinyint(3) unsigned NOT NULL DEFAULT 5 COMMENT 'Điểm đánh giá từ 1 đến 5 sao',
  `comment` text DEFAULT NULL COMMENT 'Nội dung nhận xét của khách hàng',
  `variant_info` varchar(255) DEFAULT NULL COMMENT 'Kích cỡ / Topping đã đặt',
  `reply_content` text DEFAULT NULL COMMENT 'Phản hồi từ quán / Admin',
  `replied_by` bigint(20) unsigned DEFAULT NULL COMMENT 'ID quản trị viên/nhân viên phản hồi',
  `replied_at` datetime DEFAULT NULL COMMENT 'Thời điểm phản hồi',
  `is_verified_purchase` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = Đã mua món ăn thành công',
  `helpful_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Số lượt thấy hữu ích',
  `is_approved` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1 = Hiển thị, 0 = Ẩn',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_pr_product_approved` (`product_id`,`is_approved`,`created_at`),
  KEY `idx_pr_rating` (`product_id`,`rating`),
  KEY `idx_pr_user_product` (`user_id`,`product_id`),
  KEY `idx_pr_order` (`order_id`),
  CONSTRAINT `fk_pr_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_pr_rating` CHECK (`rating` >= 1 and `rating` <= 5)
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

