--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_code` varchar(50) DEFAULT NULL COMMENT 'Mã sản phẩm (ví dụ: prod-1)',
  `restaurant_id` bigint(20) unsigned NOT NULL COMMENT 'FK quán bán món này',
  `category_id` int(10) unsigned NOT NULL COMMENT 'FK danh mục món',
  `name` varchar(200) NOT NULL COMMENT 'Tên món ăn',
  `slug` varchar(220) NOT NULL COMMENT 'Slug món ăn',
  `description` text DEFAULT NULL COMMENT 'Mô tả thành phần, khẩu phần',
  `image_url` varchar(500) DEFAULT NULL COMMENT 'Ảnh chính món ăn',
  `base_price` decimal(12,2) NOT NULL COMMENT 'Giá gốc',
  `discount_price` decimal(12,2) DEFAULT NULL COMMENT 'Giá khuyến mãi (nếu có)',
  `is_available` tinyint(1) DEFAULT 1 COMMENT '1 = Còn món, 0 = Tạm hết hàng',
  `status` enum('in_stock','out_of_stock','unavailable_today') NOT NULL DEFAULT 'in_stock',
  `is_featured` tinyint(1) DEFAULT 0 COMMENT '1 = Món ăn nổi bật / Best-seller',
  `prep_time_minutes` int(10) unsigned DEFAULT 15 COMMENT 'Thời gian chuẩn bị món dự kiến (phút)',
  `rating_avg` decimal(3,2) NOT NULL DEFAULT 0.00,
  `rating_count` int(10) unsigned NOT NULL DEFAULT 0,
  `options` longtext DEFAULT NULL COMMENT 'Biến thể & tùy chọn: size, topping, khẩu vị',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_products_restaurant` (`restaurant_id`),
  KEY `fk_products_category` (`category_id`),
  KEY `idx_products_available` (`is_available`),
  KEY `idx_products_price` (`base_price`,`discount_price`),
  KEY `idx_products_status` (`status`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_products_restaurant` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
