INSERT INTO `products` VALUES
(1,NULL,1,31,'Burger Bò Nướng Phô Mai Tan Chảy (Double Cheese)','burger-bo-nuong-pho-mai','Thịt bò Úc 100% nướng lửa than hoa thơm nức mũi, kẹp phô mai Cheddar béo ngậy, sốt BBQ đặc chế và rau xà lách tươi giòn.','https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600&auto=format&fit=crop&q=80',69000.00,0.00,1,'in_stock',1,15,4.80,5,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000}]}','2026-11-06 10:56:33','2026-11-26 08:15:47'),
(2,NULL,1,31,'Burger Bò Nướng Lửa Than Hoa (Whopper Classic)','burger-bo-whopper-classic','Thịt bò nướng lửa cỡ lớn đậm vị khói phương Tây, lát cà chua đỏ mọng và dưa chuột muối giòn tan.','https://images.unsplash.com/photo-1550547660-d9450f859349?w=600&auto=format&fit=crop&q=80',89000.00,89000.00,1,'in_stock',1,15,4.67,3,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-06 10:56:33','2026-11-26 08:15:47'),
(3,NULL,1,31,'Burger Bò Tắm Sốt Nấm Truffle Đen Thượng Hạng','burger-bo-sot-nam-truffle','Sốt kem nấm Truffle đen quý hiếm phủ trọn miếng bò nướng mọng nước, hòa quyện sốt nấm xào thơm béo.','https://images.unsplash.com/photo-1586190848861-99aa4a171e90?w=600&auto=format&fit=crop&q=80',99000.00,99000.00,1,'in_stock',1,15,4.75,4,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-06 10:56:33','2026-11-26 08:15:47'),
(4,NULL,1,31,'Burger Bò Trứng Lòng Đào Thịt Ba Chỉ Xông Khói (Bacon)','burger-bo-trung-long-dao-bacon','Sự kết hợp hoàn hảo giữa thịt bò nướng than, trứng gà lòng đào tan chảy và 2 dải bacon áp chảo giòn rụm.','https://images.unsplash.com/photo-1551782450-a2132b4ba21d?w=600&auto=format&fit=crop&q=80',82000.00,82000.00,1,'in_stock',0,15,0.00,0,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-06 10:56:33','2026-11-25 10:04:54'),
(5,NULL,1,31,'Burger Bò Cay Sốt Ớt Jalapeno Mễ Tây Cơ','burger-bo-cay-jalapeno','Dành cho tín đồ ăn cay! Ớt Jalapeno Mexico cay nồng kết hợp sốt chipotle mayo bốc khói kích thích vị giác.','https://images.unsplash.com/photo-1594212699903-ec8a3eca50f5?w=600&auto=format&fit=crop&q=80',75000.00,75000.00,1,'in_stock',0,15,4.67,3,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-26 08:15:47'),
(6,NULL,1,31,'Burger Bò 3 Tầng Siêu Khủng (Triple Beast Burger)','burger-bo-3-tang-sieu-khung','3 lớp bò Úc nướng than hoa nặng gần 400g kết hợp 3 lát phô mai Cheddar tan chảy thơm lừng ngất ngây.','https://images.unsplash.com/photo-1572802419224-296b0aeee0d9?w=600&auto=format&fit=crop&q=80',139000.00,139000.00,1,'in_stock',1,15,4.67,3,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-26 08:15:47'),
(7,NULL,1,31,'Burger Gà Phi Lê Nướng Sốt Teriyaki Mè Rang','burger-ga-phi-le-teriyaki','Thịt gà phi lê đùi rút xương ướp sốt teriyaki Nhật Bản nướng vàng óng, rắc mè trắng rang bùi thơm ngậy.','https://images.unsplash.com/photo-1606755962773-d324e0a13086?w=600&auto=format&fit=crop&q=80',65000.00,65000.00,1,'in_stock',0,15,0.00,0,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-25 10:04:54'),
(8,NULL,1,31,'Burger Cá Tuyết Phi Lê Chiên Giòn Sốt Tartar','burger-ca-tuyet-sot-tartar','Cá tuyết tươi tẩm bột xù chiên vàng rụm, thịt cá ngọt trắng mềm mịn kẹp sốt tartar chanh thì là thanh mát.','https://images.unsplash.com/photo-1521305916504-4a1121188589?w=600&auto=format&fit=crop&q=80',72000.00,72000.00,1,'in_stock',0,15,0.00,0,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-25 10:04:54'),
(9,NULL,1,31,'Burger Tôm Hoàng Gia Giòn Rụm Sốt Kem Thousand Island','burger-tom-hoang-gia','Chả tôm tươi nguyên con xay dối giữ trọn độ giòn ngọt, vỏ ngoài chiên giòn tan chấm sốt nghìn hòn đảo chua béo.','https://images.unsplash.com/photo-1561758033-d89a9ad46330?w=600&auto=format&fit=crop&q=80',79000.00,79000.00,1,'in_stock',1,15,4.67,3,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-26 08:15:47'),
(10,NULL,1,31,'Burger Bò Sốt Phô Mai Xanh (Blue Cheese Burger)','burger-bo-blue-cheese','Vị đậm đà béo sâu đặc trưng của phô mai xanh kết hợp hành tây caramen ngọt dịu và bò nướng mọng nước.','https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600&auto=format&fit=crop&q=80',89000.00,89000.00,1,'in_stock',0,15,0.00,0,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-25 10:04:54'),
(11,NULL,1,31,'Combo Burger Bò Phô Mai + Khoai Tây Múi Cau + Coca-Cola','combo-burger-bo-khoai-coca','Bữa ăn chuẩn Mỹ hoàn hảo gồm 1 Burger Bò Phô Mai, 1 phần khoai tây múi cau nướng muối giòn rụm và 1 ly Coca mát lạnh.','https://images.unsplash.com/photo-1561758033-d89a9ad46330?w=600&auto=format&fit=crop&q=80',99000.00,99000.00,1,'in_stock',1,15,4.67,3,'{\"sizes\":[{\"name\":\"Cỡ Vừa (Regular)\",\"price\":0,\"is_default\":true},{\"name\":\"Cỡ Lớn (Up-size)\",\"price\":15000,\"is_default\":false},{\"name\":\"Double Nhân Đôi (Siêu To)\",\"price\":25000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai lát Cheddar\",\"price\":10000},{\"name\":\"Thịt ba chỉ xông khói Bacon\",\"price\":15000},{\"name\":\"Khoai tây chiên nhỏ đi kèm\",\"price\":15000},{\"name\":\"Sốt phô mai cay béo ngậy\",\"price\":8000}],\"attributes\":[{\"name\":\"Hương vị & Độ cay\",\"options\":[\"Giòn truyền thống\",\"Sốt cay Hàn Quốc\",\"Lắc phô mai (+0đ)\"]}]}','2026-11-12 07:53:52','2026-11-26 08:15:47'),
