(260,NULL,13,34,'Tàu Hũ Trân Châu Đường Đen Cốt Dừa Béo Ngậy','tau-hu-tran-chau-duong-den','Tàu hũ non núng nính mềm mịn tan ngay trên đầu lưỡi, chan nước cốt dừa béo ngậy và trân châu đường đen dẻo nóng ngọt ngào.','/assets/images/foods/tau-hu-tran-chau.jpg',25000.00,25000.00,1,'in_stock',1,12,3.50,2,'{\"sizes\":[{\"name\":\"Phần Vừa\",\"price\":0,\"is_default\":true},{\"name\":\"Phần Lớn (+ Thêm món)\",\"price\":12000,\"is_default\":false}],\"toppings\":[{\"name\":\"Thêm phô mai sợi kéo béo\",\"price\":10000},{\"name\":\"Trứng cút chiên giòn\",\"price\":8000},{\"name\":\"Sốt chấm đặc biệt FASTFOOD\",\"price\":5000}],\"attributes\":[{\"name\":\"Khẩu vị\",\"options\":[\"Ăn nóng giòn liền\",\"Để riêng sốt chấm\",\"Cay vừa\"]}]}','2026-11-12 07:53:53','2026-11-26 08:15:47');
