--
-- Table structure for table `restaurants`
--

DROP TABLE IF EXISTS `restaurants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `restaurants` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` bigint(20) unsigned NOT NULL COMMENT 'FK liên kết tới users (chủ quán)',
  `name` varchar(200) NOT NULL COMMENT 'Tên quán ăn',
  `slug` varchar(220) NOT NULL COMMENT 'Đường dẫn tĩnh quán ăn',
  `description` text DEFAULT NULL COMMENT 'Giới thiệu về quán',
  `address` varchar(255) NOT NULL COMMENT 'Địa chỉ thực tế',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT 'Tọa độ vĩ độ cho tính khoảng cách',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT 'Tọa độ kinh độ cho tính khoảng cách',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Hotline quán',
  `email` varchar(191) DEFAULT NULL COMMENT 'Email liên hệ quán',
  `banner_url` varchar(500) DEFAULT NULL COMMENT 'Ảnh bìa quán',
  `logo_url` varchar(500) DEFAULT NULL COMMENT 'Logo quán',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '1 = Mở cửa nhận đơn, 0 = Đóng cửa',
  `is_verified` tinyint(1) DEFAULT 0 COMMENT 'Đã được Admin duyệt xác thực',
  `rating_avg` decimal(3,2) DEFAULT 5.00 COMMENT 'Điểm đánh giá trung bình (1-5)',
  `rating_count` int(10) unsigned DEFAULT 0 COMMENT 'Số lượt đánh giá',
  `opening_time` time NOT NULL DEFAULT '07:00:00' COMMENT 'Giờ mở cửa',
  `closing_time` time NOT NULL DEFAULT '22:00:00' COMMENT 'Giờ đóng cửa',
  `min_order_amount` decimal(12,2) DEFAULT 0.00 COMMENT 'Giá trị đơn hàng tối thiểu',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `fk_restaurants_owner` (`owner_id`),
  KEY `idx_restaurants_slug` (`slug`),
  KEY `idx_restaurants_rating` (`rating_avg`),
  KEY `idx_restaurants_location` (`latitude`,`longitude`),
  CONSTRAINT `fk_restaurants_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

